import type { Metadata } from "next";
import Navbar from "@/components/Navbar";
import Footer from "@/components/Footer";
import Link from "next/link";
import { ArrowLeft } from "lucide-react";

export const metadata: Metadata = {
  title: "Galeri Foto",
  description: "Kumpulan karya foto.",
};

export default async function CategoryGalleryPage({ params }: { params: Promise<{ category: string }> }) {
  const { category } = await params;
  
  const categoryName = category.charAt(0).toUpperCase() + category.slice(1);
  
  // Create an array of 20 placeholder images
  const photos = Array.from({ length: 20 }).map((_, i) => ({
    id: i + 1,
    src: `https://images.unsplash.com/photo-1511285560929-80b456fea0bc?q=80&w=800&auto=format&fit=crop&sig=${category}${i}`, // Added sig to try to differentiate caching
    label: `${categoryName} Photo ${i + 1}`,
  }));

  // Let's customize the default image base per category to have variety
  const categoryImages: Record<string, string> = {
    prewedding: "1519741497674-611481863552",
    sangjit: "1544591572-132d7319c5c7",
    pemberkatan: "1522060377042-78d103194a2f",
    wedding: "1511285560929-80b456fea0bc",
    maternity: "1527814766155-2287c2fb2d35",
    birthday: "1530103862676-de8892b12a15",
    graduation: "1523050854058-8df90110c9f1"
  };

  const imageId = categoryImages[category] || "1511285560929-80b456fea0bc";
  
  const galleryPhotos = Array.from({ length: 20 }).map((_, i) => {
    // We add some random width/height query params to make placeholder slightly different or use random ones
    return {
      id: i + 1,
      src: `https://images.unsplash.com/photo-${imageId}?q=80&w=800&auto=format&fit=crop&sig=${i}`,
      label: `${categoryName} Photo ${i + 1}`,
    }
  });

  return (
    <>
      <Navbar />
      <main className="flex-1 px-6 pb-32 pt-32">
        <div className="mx-auto max-w-7xl">
          <div className="mb-12">
            <Link href="/galeri" className="inline-flex items-center text-sm font-medium text-muted hover:text-foreground transition-colors mb-6">
              <ArrowLeft className="mr-2 h-4 w-4" />
              Kembali ke Kategori
            </Link>
            <h1 className="font-heading text-4xl font-bold tracking-tight text-foreground sm:text-5xl">
              Galeri {categoryName}
            </h1>
            <p className="mt-4 text-lg text-muted font-light leading-relaxed">
              Momen-momen indah dari sesi {categoryName.toLowerCase()} yang kami abadikan.
            </p>
          </div>

          <div className="columns-1 sm:columns-2 lg:columns-4 gap-4 space-y-4">
            {galleryPhotos.map((photo) => (
              <div
                key={photo.id}
                className="group relative w-full break-inside-avoid overflow-hidden rounded-2xl bg-surface-2"
              >
                <img
                  src={photo.src}
                  alt={photo.label}
                  loading="lazy"
                  className="w-full h-auto object-cover transition-transform duration-700 ease-in-out group-hover:scale-105"
                />
                
                <div className="absolute inset-0 bg-gradient-to-t from-black/60 via-transparent to-transparent opacity-0 transition-opacity duration-300 group-hover:opacity-100" />
              </div>
            ))}
          </div>
        </div>
      </main>
      <Footer />
    </>
  );
}
